<style>
*{box-sizing:border-box}html,body{width:100%;height:100%;margin:0;overflow:hidden;background:#020812;color:#dff7ff;font-family:Consolas,monospace}#viewport{position:fixed;inset:0;overflow:hidden;perspective:950px;perspective-origin:50% 46%;background:radial-gradient(ellipse at 50% 46%,#174669 0,#071b2d 48%,#020812 100%)}#room{position:absolute;inset:-3%;transform-style:preserve-3d;transform:rotateY(0deg);transition:transform .12s ease-out}.stars{position:absolute;inset:0 0 49%;background:radial-gradient(1px 1px at 13% 25%,#e8faff 60%,transparent),radial-gradient(1px 1px at 38% 13%,#9edfff 60%,transparent),radial-gradient(1px 1px at 75% 23%,#fff 60%,transparent),radial-gradient(1px 1px at 88% 48%,#d4f6ff 60%,transparent),radial-gradient(1px 1px at 57% 37%,#fff 60%,transparent);background-size:260px 190px;opacity:.82}.planet{position:absolute;left:43%;top:18%;width:18%;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle at 32% 28%,#b9e9ff 0,#5596b6 25%,#1a4566 58%,#061525 77%);box-shadow:0 0 35px #43bdff77}.planet:after{content:"";position:absolute;inset:53% -35% -18%;border-radius:50%;background:linear-gradient(180deg,#40bff088,#061323 64%);filter:blur(7px)}.window{position:absolute;z-index:2;left:24%;right:24%;top:9%;height:32%;border:13px solid #263b49;border-radius:48% 48% 14% 14%;background:radial-gradient(ellipse at 50% 80%,#154c6a,#071a2c 72%);box-shadow:inset 0 0 0 3px #9bb7bd,inset 0 0 35px #31bcf455,0 0 0 5px #0b1925,0 0 25px #35aeff55;overflow:hidden}.window:before,.window:after{content:"";position:absolute;background:linear-gradient(90deg,transparent,#b9e9ffbb,transparent);height:5px;width:130%;left:-15%;top:50%;transform:rotate(-17deg);box-shadow:0 0 11px #4ccaff}.window:after{top:72%;transform:rotate(17deg);opacity:.25}.window .planet{left:37%;top:8%;width:30%}.cockpit-frame{position:absolute;z-index:4;left:16%;right:16%;top:35%;height:26%;background:linear-gradient(180deg,#273844,#121f2a 64%,#08131d);border:8px solid #71818a;clip-path:polygon(8% 0,92% 0,100% 100%,0 100%);box-shadow:0 12px 22px #000b;transform:translateZ(15px)}.dash{position:absolute;left:4%;right:4%;bottom:5%;height:27%;border:2px solid #52717c;border-radius:12px 12px 3px 3px;background:linear-gradient(180deg,#285668,#102b39 60%,#07141e);box-shadow:0 -6px 20px #3dd5ff33;display:flex;align-items:center;justify-content:space-around;padding:0 4%}.screen{height:66%;width:27%;border:2px solid #6d9aa2;background:repeating-linear-gradient(0deg,#07334b 0 5px,#0c5470 6px 7px);box-shadow:inset 0 0 20px #02caff55;position:relative}.screen:after{content:"";position:absolute;inset:20%;border:2px solid #37d9ee;border-radius:50%;box-shadow:0 0 10px #28cfff}.pilot-seat{position:absolute;z-index:5;left:50%;top:40%;width:16%;height:33%;transform:translateX(-50%) translateZ(20px)}.pilot-chair{position:absolute;left:17%;right:17%;bottom:0;height:72%;border:5px solid #374a58;border-radius:24px 24px 6px 6px;background:linear-gradient(90deg,#101b25,#293845 48%,#0a141d);box-shadow:0 8px 14px #000}.pilot-body{position:absolute;bottom:31%;left:30%;width:40%;height:42%;border-radius:35% 35% 16% 16%;background:linear-gradient(90deg,#101e2d,#293b50 45%,#111e2d);box-shadow:inset 0 0 0 3px #456078}.pilot-body:before{content:"";position:absolute;left:25%;top:-34%;width:50%;aspect-ratio:1;border-radius:48%;background:radial-gradient(circle at 40% 35%,#303a43,#080e15 68%);box-shadow:0 0 0 5px #182631}.pilot-body:after{content:"";position:absolute;left:28%;top:15%;width:44%;height:8%;background:#d5a53b;box-shadow:0 20px 0 #142536,0 34px 0 #142536}.ceiling{position:absolute;z-index:3;left:0;right:0;top:-17%;height:37%;background:repeating-linear-gradient(90deg,#0b1822 0 8%,#233746 8.3% 8.8%,#101e29 9.5% 18%),linear-gradient(#243744,#07131e);clip-path:polygon(0 0,100% 0,77% 100%,23% 100%);border-bottom:10px solid #344e5d;transform:translateZ(25px)}.ceiling:after{content:"";position:absolute;left:25%;right:25%;bottom:8%;height:9px;background:#d9efff;box-shadow:0 0 15px #39bfff, -290px 20px 0 -2px #ffce8d,290px 20px 0 -2px #ffce8d}.wall{position:absolute;z-index:3;top:12%;bottom:0;width:28%;background:repeating-linear-gradient(180deg,transparent 0 8%,#627783 8.2% 8.7%,transparent 9% 18%),repeating-linear-gradient(90deg,#101f2b 0 17%,#283a46 17.5% 19%,#142431 20% 39%);border:7px solid #263b49;box-shadow:inset 0 0 25px #02080e,0 0 16px #000}.wall.left{left:-6%;transform:perspective(700px) rotateY(22deg);transform-origin:right center}.wall.right{right:-6%;transform:perspective(700px) rotateY(-22deg);transform-origin:left center}.wall:after{content:"";position:absolute;top:14%;bottom:14%;left:12%;right:12%;border:3px solid #526875;background:linear-gradient(90deg,#0a1720,#192a36 55%,#0b1822);box-shadow:inset 0 0 24px #000}.lightbar{position:absolute;z-index:4;top:16%;bottom:9%;width:9px;background:linear-gradient(180deg,#fff,#ffbd7a);box-shadow:0 0 10px #ffbd7a,0 0 30px #ff9f4b}.lightbar.l{left:21%}.lightbar.r{right:21%}.floor{position:absolute;z-index:2;left:-20%;right:-20%;height:69%;bottom:-28%;transform:rotateX(67deg);transform-origin:50% 0;background:repeating-linear-gradient(90deg,transparent 0 9.5%,#08131d 9.7% 10.1%,transparent 10.3% 20%),repeating-linear-gradient(0deg,#233b4b 0 9.2%,#0a1925 9.5% 10.2%,#244962 10.5% 19.2%,#101e29 19.5% 20%);border-top:8px solid #516b78;box-shadow:inset 0 12px 22px #000}.floor:before{content:"";position:absolute;left:39%;right:39%;top:0;bottom:0;background:linear-gradient(90deg,#ffca8a,#fff 34%,#101a22 40% 60%,#fff 66%,#ffc581);opacity:.85;filter:blur(1px)}.runner{position:absolute;z-index:7;top:46%;bottom:0;width:12%;pointer-events:none}.seat{position:absolute;bottom:10%;width:32%;height:37%;transform-style:preserve-3d}.seat:before{content:"";position:absolute;left:0;right:0;top:0;height:64%;border:5px solid #465966;border-radius:16px 16px 4px 4px;background:linear-gradient(100deg,#09131d,#283943 48%,#0c1821);box-shadow:0 8px 12px #000}.seat:after{content:"";position:absolute;left:10%;right:10%;bottom:0;height:32%;background:linear-gradient(90deg,#101a22,#314551,#111c25);border:3px solid #50616b;border-radius:5px}.left-seats{left:1%}.right-seats{right:1%}.seat.s1{left:5%;transform:scale(.72);bottom:40%}.seat.s2{left:21%;transform:scale(.88);bottom:24%}.seat.s3{left:43%;transform:scale(1.08);bottom:6%}.right-seats .seat.s1{right:5%;left:auto}.right-seats .seat.s2{right:21%;left:auto}.right-seats .seat.s3{right:43%;left:auto}.crate{position:absolute;z-index:8;bottom:3%;width:18%;height:20%;transform-style:preserve-3d;filter:drop-shadow(0 12px 12px #000)}.crate.left{left:4%;background:linear-gradient(90deg,#ad791f,#d4a33a 48%,#795315);border:6px solid #253541}.crate.right{right:4%;background:linear-gradient(90deg,#172734,#34434d 48%,#111d27);border:6px solid #263945}.crate:before{content:"";position:absolute;inset:10%;border:4px solid #293945;box-shadow:inset 0 0 0 2px #87918a,0 0 0 2px #0a141b;background:repeating-linear-gradient(0deg,transparent 0 15%,#253540 15.5% 18%,transparent 18.5%)}.crate:after{content:"";position:absolute;top:-15px;left:-6px;right:-6px;height:18px;background:linear-gradient(#d1a342,#765417);border:3px solid #273640;transform:skewX(-12deg)}.crate.right:after{background:linear-gradient(#52606a,#17232b)}.strips{position:absolute;inset:0;z-index:5;pointer-events:none;background:linear-gradient(90deg,transparent 0 4%,#64d7ff 4.2% 4.35%,transparent 4.5% 95.5%,#64d7ff 95.7% 95.85%,transparent 96%),linear-gradient(180deg,#02081244,transparent 36% 78%,#02081288)}#avatars{position:absolute;inset:0;z-index:9;transform-style:preserve-3d;pointer-events:none}.avatar{position:absolute;width:52px;height:100px;transform:translate(-50%,-50%);transition:left .22s linear,top .22s linear;filter:drop-shadow(0 5px 5px #000);text-align:center}.avatar .person{position:absolute;left:15px;bottom:17px;width:23px;height:42px;border-radius:9px 9px 4px 4px;background:linear-gradient(90deg,#101f2c,#3d6880,#132536);border:1px solid #53798a}.avatar .person:before{content:"";position:absolute;left:3px;top:-24px;width:15px;height:19px;border-radius:45%;background:radial-gradient(circle at 50% 40%,#e1b997,#8e624a 72%);box-shadow:0 -5px 0 #17202a}.avatar b{position:absolute;left:50%;bottom:0;transform:translateX(-50%);padding:2px 4px;max-width:90px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;background:#06131ddd;border:1px solid #5e91a1;color:#dff8ff;font-size:9px}.avatar.local .person{background:linear-gradient(90deg,#114943,#39a58d,#0b3836);border-color:#72e4c5}.avatar[hidden]{display:none}#hud{position:absolute;z-index:20;left:16px;top:15px;padding:10px 13px;background:#04111bd9;border:1px solid #45bdd777;box-shadow:0 0 18px #0aa9df22}#hud b{display:block;color:#8cecff;letter-spacing:.13em;font-size:12px}#hud small{display:block;color:#9cb7c1;margin-top:4px;font-size:9px}#camera{position:absolute;z-index:20;right:16px;top:15px;padding:9px 12px;border:1px solid #5dbdce;background:#071a27dd;color:#dcfaff;font:10px Consolas;cursor:pointer}#help{position:absolute;z-index:20;left:16px;bottom:15px;padding:8px 10px;background:#04111bd9;color:#c0e8ee;font-size:9px;border-left:2px solid #51d5ee}#pad{position:absolute;right:14px;bottom:13px;z-index:20;display:grid;grid-template-columns:repeat(3,40px);gap:4px;touch-action:none}#pad button{height:38px;border:1px solid #62c5d5;background:#061b28df;color:white;font-size:16px;touch-action:none}#pad [data-move="forward"]{grid-column:2}#pad [data-move="left"]{grid-column:1}#pad [data-move="back"]{grid-column:2}#pad [data-move="right"]{grid-column:3}#loading{position:absolute;inset:0;display:grid;place-items:center;background:#020812;color:#82eaff;z-index:30;letter-spacing:.12em}@media(max-width:650px){#hud{left:8px;top:8px}#camera{right:8px;top:8px}.wall{width:34%}.crate{width:22%;height:17%}.seat{width:39%}.avatar{scale:.8}#help{display:none}}
</style>
