<body>
<main id="viewport" aria-label="Cabine 3D da nave"><div id="room">
 <div class="stars"></div><div class="planet"></div><div class="window"><div class="planet"></div></div>
 <div class="ceiling"></div><div class="wall left"></div><div class="wall right"></div><i class="lightbar l"></i><i class="lightbar r"></i>
 <div class="floor"></div><div class="cockpit-frame"><div class="dash"><i class="screen"></i><i class="screen"></i><i class="screen"></i></div></div>
 <div class="pilot-seat"><div class="pilot-chair"></div><div class="pilot-body"></div></div>
 <div class="runner left-seats"><i class="seat s1"></i><i class="seat s2"></i><i class="seat s3"></i></div><div class="runner right-seats"><i class="seat s1"></i><i class="seat s2"></i><i class="seat s3"></i></div>
 <div class="crate left"></div><div class="crate right"></div><div class="strips"></div><div id="avatars"></div>
</div></main>
<div id="hud"><b><?= $shipId ?></b><small>COMPARTIMENTO DE PASSAGEIROS E CARGA</small></div>
<button id="camera" type="button">CÂMERA: 1ª PESSOA</button><div id="help">WASD / SETAS — ANDAR · MOUSE — OLHAR · V — CÂMERA</div>
<div id="pad"><button data-move="forward">▲</button><button data-move="left">◀</button><button data-move="back">▼</button><button data-move="right">▶</button></div><div id="loading">INICIALIZANDO CABINE...</div>
<script>
'use strict';(()=>{
 const avatars=new Map(),pressed=new Set(),room=document.querySelector('#room'),layer=document.querySelector('#avatars'),camera=document.querySelector('#camera');
 const pos={x:0,z:8},velocity=4;let yaw=0,third=false,pointer=false,last=performance.now();
 function place(el,x,z){el.style.left=(50+x*3.15)+'%';el.style.top=(61-z*1.48)+'%';el.style.zIndex=String(20-Math.round(z))}
 function addPlayer(id,data={}){id=String(id);let entry=avatars.get(id);if(!entry){const el=document.createElement('div');el.className='avatar';el.innerHTML='<span class="person"></span><b></b>';layer.append(el);entry={el,target:{x:0,z:0},rotation:0};avatars.set(id,entry)}updatePlayer(id,data);return entry.el}
 function updatePlayer(id,data={}){let entry=avatars.get(String(id));if(!entry){addPlayer(id,data);return}if(Number.isFinite(Number(data.x)))entry.target.x=Number(data.x);if(Number.isFinite(Number(data.z)))entry.target.z=Number(data.z);if(data.rotation!==undefined)entry.rotation=Number(data.rotation)||0;entry.el.querySelector('b').textContent=data.name||'Passageiro';place(entry.el,entry.target.x,entry.target.z)}
 function removePlayer(id){const entry=avatars.get(String(id));if(entry){entry.el.remove();avatars.delete(String(id))}}
 function move(dt){let f=(pressed.has('KeyW')||pressed.has('ArrowUp')?1:0)-(pressed.has('KeyS')||pressed.has('ArrowDown')?1:0),s=(pressed.has('KeyD')||pressed.has('ArrowRight')?1:0)-(pressed.has('KeyA')||pressed.has('ArrowLeft')?1:0);if(!f&&!s)return;let n=Math.hypot(f,s);f/=n;s/=n;pos.x=Math.max(-5.2,Math.min(5.2,pos.x+(Math.sin(yaw)*f+Math.cos(yaw)*s)*velocity*dt));pos.z=Math.max(-10.7,Math.min(11.2,pos.z+(-Math.cos(yaw)*f+Math.sin(yaw)*s)*velocity*dt));const local=document.querySelector('.avatar.local');if(local)place(local,pos.x,pos.z)}
 function tick(now){const dt=Math.min(.05,(now-last)/1000);last=now;move(dt);for(const entry of avatars.values()){const a=.18;entry.el.style.left=(50+entry.target.x*3.15)+'%';entry.el.style.top=(61-entry.target.z*1.48)+'%'}requestAnimationFrame(tick)}
 function toggle(){third=!third;camera.textContent=third?'CÂMERA: 3ª PESSOA':'CÂMERA: 1ª PESSOA';let local=avatars.get('local');if(local)local.el.hidden=!third}
 camera.addEventListener('click',toggle);document.addEventListener('keydown',e=>{if(e.code==='KeyV'){toggle();return}if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code)){pressed.add(e.code);e.preventDefault()}});document.addEventListener('keyup',e=>pressed.delete(e.code));window.addEventListener('blur',()=>pressed.clear());
 const pointerTarget=document.querySelector('#viewport');pointerTarget.addEventListener('click',()=>pointerTarget.requestPointerLock?.());document.addEventListener('pointerlockchange',()=>pointer=document.pointerLockElement===pointerTarget);document.addEventListener('mousemove',e=>{if(pointer){yaw=Math.max(-.45,Math.min(.45,yaw-e.movementX*.0015));room.style.transform='rotateY('+(-yaw*14)+'deg)'}});
 document.querySelectorAll('#pad button').forEach(button=>{const key={forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD'}[button.dataset.move];button.addEventListener('pointerdown',e=>{e.preventDefault();pressed.add(key);button.setPointerCapture(e.pointerId)});for(const name of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(name,()=>pressed.delete(key))});
 window.Cabine3D={addPlayer,updatePlayer,removePlayer,setPilot(data={}){const name=data.name||'Piloto';document.querySelector('#hud b').textContent=<?= json_encode($shipId, JSON_UNESCAPED_UNICODE) ?>+' · '+name},getLocalPosition(){return{x:pos.x,y:0,z:pos.z,rotation:yaw}},setLocalPosition(x,z){if(Number.isFinite(Number(x))&&Number.isFinite(Number(z))){pos.x=Math.max(-5.2,Math.min(5.2,Number(x)));pos.z=Math.max(-10.7,Math.min(11.2,Number(z)));const local=avatars.get('local');if(local)place(local.el,pos.x,pos.z)}},changeCamera:toggle,getPassengerCount(){return avatars.size}};
 const self=addPlayer('local',{name:'VOCÊ'});self.classList.add('local');self.hidden=true;document.querySelector('#loading').remove();requestAnimationFrame(tick);
})();
</script></body></html>
